<script setup>
import {ref} from 'vue';
import {Head,usePage} from '@inertiajs/vue3';
import AdminLayout from '../../Components/AdminLayout.vue';
const props=defineProps({enabled:Boolean,tokens:Array,canManageTokens:Boolean,required:Boolean});
const page=usePage();
const busy=ref(false),error=ref(''),message=ref(''),confirmed=ref(false),enabled=ref(props.enabled),qr=ref(''),secret=ref(''),codes=ref([]),token=ref(''),tokens=ref(props.tokens);
const password=ref(''),code=ref(''),tokenName=ref('');
const profile=ref({name:page.props.auth.user.name,email:page.props.auth.user.email});
const credentials=ref({current_password:'',password:'',password_confirmation:''});
async function request(path,method='GET',data){const response=await fetch(path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:data?JSON.stringify(data):undefined});const result=response.status===204?{}:await response.json().catch(()=>({}));if(!response.ok)throw new Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Não foi possível concluir. Confirme novamente a palavra-passe.');return result;}
async function run(action){busy.value=true;error.value='';message.value='';try{await action();}catch(e){error.value=e.message;}finally{busy.value=false;}}
function confirm(){run(async()=>{await request('/user/confirm-password','POST',{password:password.value});confirmed.value=true;password.value='';message.value='Acesso confirmado.';});}
async function loadSetup(){const data=await request('/user/two-factor-qr-code');qr.value=data.svg;secret.value=(await request('/user/two-factor-secret-key')).secretKey;}
function enable(){run(async()=>{await request('/user/two-factor-authentication','POST');await loadSetup();});}
function verify(){run(async()=>{await request('/user/confirmed-two-factor-authentication','POST',{code:code.value});enabled.value=true;qr.value='';secret.value='';codes.value=await request('/user/two-factor-recovery-codes');message.value='Autenticação em dois passos ativada. Guarde os códigos de recuperação.';});}
function disable(){if(confirmDisable())run(async()=>{await request('/user/two-factor-authentication','DELETE');enabled.value=false;codes.value=[];message.value='Autenticação em dois passos desativada. Ative novamente para aceder às operações administrativas.';});}
function confirmDisable(){return window.confirm('Desativar a autenticação em dois passos?');}
function createToken(){run(async()=>{const result=await request('/admin/tokens','POST',{name:tokenName.value});token.value=result.token;tokens.value=result.tokens;tokenName.value='';});}
function revoke(id){run(async()=>{await request('/admin/tokens/'+id,'DELETE');tokens.value=tokens.value.filter(t=>t.id!==id);message.value='Token revogado.';});}
</script>
<template><AdminLayout><Head title="Segurança"/><div class="page-heading"><div><span class="eyebrow">Conta</span><h1>Perfil e segurança</h1><p>Proteja a conta, atualize os seus dados e controle o acesso à API.</p></div></div><p v-if="required&&!enabled" class="notice">Ative a autenticação em dois passos para usar as funções administrativas.</p><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><form class="panel admin-form" @submit.prevent="run(async()=>{await request('/user/profile-information','PUT',profile);message='Perfil atualizado.';})"><h2>Perfil</h2><div class="form-grid"><div class="field"><label for="profile-name">Nome</label><input id="profile-name" v-model="profile.name" required></div><div class="field"><label for="profile-email">Email</label><input id="profile-email" type="email" v-model="profile.email" required></div></div><button class="button" :disabled="busy">Atualizar perfil</button></form><form class="panel admin-form" @submit.prevent="run(async()=>{await request('/user/password','PUT',credentials);credentials={current_password:'',password:'',password_confirmation:''};message='Palavra-passe atualizada.';})"><h2>Alterar palavra-passe</h2><div class="form-grid"><div class="field"><label for="current-password">Palavra-passe atual</label><input id="current-password" type="password" autocomplete="current-password" v-model="credentials.current_password" required></div><div class="field"><label for="new-password">Nova palavra-passe</label><input id="new-password" type="password" autocomplete="new-password" v-model="credentials.password" minlength="12" required></div><div class="field"><label for="repeat-password">Repetir nova palavra-passe</label><input id="repeat-password" type="password" autocomplete="new-password" v-model="credentials.password_confirmation" required></div></div><button class="button" :disabled="busy">Alterar palavra-passe</button></form><section class="panel admin-form"><h2>Autenticação em dois passos</h2><p>Estado: <strong>{{enabled?'Ativada':'Não ativada'}}</strong></p><form v-if="!confirmed" @submit.prevent="confirm"><div class="field"><label for="confirm-password">Confirme a palavra-passe para gerir a segurança</label><input id="confirm-password" type="password" autocomplete="current-password" v-model="password" required></div><button class="button" :disabled="busy">Confirmar acesso</button></form><template v-else><div class="button-row"><button v-if="!enabled" class="button" :disabled="busy" @click="enable">Configurar autenticador</button><button v-if="enabled" class="button outline" :disabled="busy" @click="run(async()=>{codes=await request('/user/two-factor-recovery-codes');})">Ver códigos de recuperação</button><button v-if="enabled" class="text-link" :disabled="busy" @click="disable">Desativar</button></div><form v-if="qr" @submit.prevent="verify"><p>Leia o código com a sua aplicação autenticadora e confirme o código de seis dígitos.</p><div class="qr-code" v-html="qr"></div><p class="secret">Chave: {{secret}}</p><div class="field"><label for="totp">Código do autenticador</label><input id="totp" v-model="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required></div><button class="button" :disabled="busy">Ativar autenticação</button></form><div v-if="codes.length"><p>Guarde estes códigos em local seguro. Cada código pode ser usado uma vez.</p><pre class="secret">{{codes.join('\n')}}</pre><button class="button outline small" :disabled="busy" @click="run(async()=>{await request('/user/two-factor-recovery-codes','POST');codes=await request('/user/two-factor-recovery-codes');})">Regenerar códigos</button></div><a v-if="enabled" href="/admin/dashboard" class="button">Ir para o dashboard ↗</a></template></section><section v-if="canManageTokens" class="panel admin-form"><h2>Tokens da API</h2><p>Tokens de leitura válidos por 30 dias.</p><form v-if="confirmed&&enabled" @submit.prevent="createToken"><div class="field"><label for="token-name">Nome da integração</label><input id="token-name" v-model="tokenName" maxlength="100" required></div><button class="button" :disabled="busy">Criar token</button></form><div v-if="token" class="notice"><p>Copie agora. O token completo não será exibido novamente.</p><pre class="secret">{{token}}</pre></div><div v-for="t in tokens" :key="t.id" class="access-card actions"><span>{{t.name}} · expira em {{new Date(t.expires_at).toLocaleDateString('pt-AO')}}</span><button :disabled="busy" @click="revoke(t.id)">Revogar</button></div></section></AdminLayout></template>
